import { query } from '../db.js';
import { UserRepository } from './user-repository.js';

export class OrderRepository {
  findActive() {
    return new UserRepository().findActive().then((users) => {
      const activeUserIds = new Set(users.map((user) => user.id));
      return new Promise((resolve, reject) => {
        query('orders', (order) => order.deleted_at === null && activeUserIds.has(order.user_id),
          (err, rows) => (err ? reject(err) : resolve(rows)));
      });
    });
  }

  findById(id) {
    return this.findActive().then((orders) =>
      orders.find((order) => order.id === id) ?? null);
  }

  findByUser(userId) {
    return this.findActive().then((orders) =>
      orders.filter((order) => order.user_id === userId));
  }

  findPaid() {
    return this.findActive().then((orders) =>
      orders.filter((order) => order.status === 'paid'));
  }

  findQuotes() {
    return this.findActive().then((orders) =>
      orders.filter((order) => order.status === 'quote'));
  }
}

